def min_steps(grid):
    from collections import deque
    R, C = len(grid), len(grid[0])
    if grid[0][0] == '#' or grid[R-1][C-1] == '#':
        return -1
    q, seen = deque([(0, 0, 0)]), {(0, 0)}
    while q:
        r, c, d = q.popleft()
        if (r, c) == (R - 1, C - 1):
            return d
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == '.' and (nr, nc) not in seen:
                seen.add((nr, nc))
                q.append((nr, nc, d + 1))
    return -1

def count_islands(grid):
    if not grid:
        return 0
    R, C = len(grid), len(grid[0])
    seen = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            a, b = stack.pop()
            if (a, b) in seen or not (0 <= a < R and 0 <= b < C) or grid[a][b] != '1':
                continue
            seen.add((a, b))
            stack += [(a + 1, b), (a - 1, b), (a, b + 1), (a, b - 1)]
    n = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] == '1' and (r, c) not in seen:
                n += 1
                dfs(r, c)
    return n

